// Original layered SVG character treatment, animated poses and an accessible inspection stage.
let operatorSerial=0,operatorReturn=null;const operatorFrames=new Map();
const baseOperatorSVG=heroSVG;heroSVG=function(id=profile.hero,extra='',look,weapon,equipment){let svg=baseOperatorSVG(id,extra,look,weapon,equipment),uid='op'+(++operatorSerial);svg=svg.replace('<path d="M144 178','<path class="operator-tail" d="M144 178').replace(/<path d="M72 191L70 222 94 222 102 190M125 190L129 222 154 222 148 189"([^>]*)\/>/,'<path class="operator-leg-left" d="M72 191L70 222 94 222 102 190Z"$1/><path class="operator-leg-right" d="M125 190L129 222 154 222 148 189Z"$1/>').replace(/<path d="M64 152L43 170 51 190 78 172M153 151L179 169 168 189 143 171"([^>]*)\/>/,'<path class="operator-arm-left" d="M64 152L43 170 51 190 78 172Z"$1/><path class="operator-arm-right" d="M153 151L179 169 168 189 143 171Z"$1/>').replace('<g data-weapon=','<g class="operator-weapon" data-weapon=').replace('<g data-breed-art=','<g class="operator-head" data-breed-art=');const at=svg.indexOf('>')+1;const defs=`<defs><linearGradient id="${uid}shade" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#e9ffff" stop-opacity=".25"/><stop offset=".45" stop-color="#ffffff" stop-opacity="0"/><stop offset="1" stop-color="#102338" stop-opacity=".3"/></linearGradient></defs>`;svg=svg.slice(0,at)+defs+svg.slice(at);svg=svg.replace('</svg>',`<path d="M74 145L91 153 88 174 72 165Z M133 153L148 145 151 166 135 175Z" fill="#172d46" opacity=".65"/><path d="M80 149L85 171M140 150L145 170M79 197L94 195M130 195L146 197" fill="none" stroke="#cfebeb" stroke-opacity=".65" stroke-width="2"/><rect x="98" y="176" width="27" height="6" rx="2" fill="#8bc8d7" stroke="#23344c" stroke-width="1.5"/><path d="M64 74Q60 45 111 44Q160 44 164 76L158 119Q150 150 111 155Q69 147 64 119Z" fill="url(#${uid}shade)" pointer-events="none"/><path d="M78 62Q102 47 128 55M74 85L79 81M151 86L147 81" fill="none" stroke="#effcf1" stroke-opacity=".45" stroke-width="2"/><g class="operator-muzzle" opacity="0"><path d="M204 166L219 156 215 168 229 173 215 177 219 190 204 181Z" fill="#ebffc8"/></g></svg>`);return svg};
petPortrait=function(h){return heroSVG(h.id,'',h.look,h.weapon,{...equipmentForPeer(h),level:h.playerLevel||h.level||playerLevel()},h.cosmetic).replace('viewBox="0 0 220 250"','viewBox="25 18 175 166"').replace('role="img"','role="img" class="operator-portrait"')};
function operatorFrame(h,index=0,firing=false){const cosmetic=typeof cosmeticForHero==='function'?cosmeticForHero(h):{},key=h.id+JSON.stringify(h.look||lookFor(h.id))+h.weapon+JSON.stringify(cosmetic)+JSON.stringify([h.armour,h.shieldItem])+':'+index+':'+firing;if(operatorFrames.has(key))return operatorFrames.get(key);if(typeof window.Image!=='function')return getAvatarSprite(h);let svg=heroSVG(h.id,'',h.look,h.weapon,{armour:h.armour||'none',shield:h.shieldItem||'none',level:h.playerLevel||playerLevel()},h.cosmetic),phase=Math.sin(index*Math.PI/4);const pose=(name,transform)=>{svg=svg.replace('class="'+name+'"','class="'+name+'" transform="'+transform+'"')};if(index>=0){pose('operator-leg-left',`rotate(${phase*12} 85 192)`);pose('operator-leg-right',`rotate(${-phase*12} 139 192)`);pose('operator-arm-left',`rotate(${-phase*8} 67 151)`);pose('operator-tail',`rotate(${phase*9} 145 178)`)}if(firing)svg=svg.replace('class="operator-muzzle" opacity="0"','class="operator-muzzle" opacity="1"');const image=new window.Image();image.decoding='async';image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);if(operatorFrames.size>=128)operatorFrames.delete(operatorFrames.keys().next().value);operatorFrames.set(key,image);return image}
function paintOperator(c,g,x=g.x,y=g.y,size=70,label=true){const t=g.elapsed||0,h=g.hero,phase=g.moving?Math.floor(t*13)%8:0,firing=!!g.operatorFire||g.zaps>0,img=operatorFrame(h,phase,firing);if(!img?.complete||!img.naturalWidth)return false;const scale=size/98,bob=g.moving?Math.abs(Math.sin(t*13))*.9:Math.sin(t*2)*.6;c.save();c.translate(x,y);c.scale(scale,scale);ellipse(c,4,25,33,11,'#05152988');c.strokeStyle=(g.teamColour||'#a7dfd4')+'77';c.lineWidth=2;c.beginPath();c.ellipse(0,24,34,13,0,0,7);c.stroke();if(g.moving)for(let i=0;i<3;i++){const k=((t*3+i*.33)%1);ellipse(c,-12+i*12,25+k*12,3*(1-k),2*(1-k),'#cfddd233')}if(g.invincible>0&&Math.floor(t*12)%2)c.globalAlpha=.65;c.save();c.rotate(g.moving?Math.sin(t*6.5)*.018:0);c.drawImage(img,-49,-85+bob,98,112);c.restore();if(g.shieldCharge>0){c.strokeStyle='#82dfe788';c.lineWidth=2;c.beginPath();c.ellipse(0,-16,43,51,0,t*.3,t*.3+5.4);c.stroke()}if(label){const name=String(h.name||'Companion').slice(0,20);c.font='700 11px system-ui';c.textAlign='center';roundRect(c,-58,-103,116,18,4,'#0a1d32cf','#6f94a566');c.fillStyle='#e2f4f3';c.fillText(name,0,-90)}c.restore();return true}
const fallbackOperator=drawBreedAvatar;drawBreedAvatar=function(c,g){return paintOperator(c,g)||fallbackOperator(c,g)};
miniPet=function(c,g,x,y,size=75){if(!paintOperator(c,g,x,y,size,false)){const image=getAvatarSprite(g.hero);if(image?.complete&&image.naturalWidth)c.drawImage(image,x-size/2,y-size*1.13,size,size*1.13)}};
drawPetPlayer=function(c,g){if(!live?.battleStarted){if(!drawBreedAvatar(c,g))drawSimplePetPlayer(c,g);return}for(const p of Object.values(live.units)){const mine=p.id===live.selfId,h=getBattleHero(p.hero,p.level,equipmentForPeer(p));if(!mine){const blend=movementBlend(g.frameDelta,18);p.renderX=(p.renderX??p.x)+(p.x-(p.renderX??p.x))*blend;p.renderY=(p.renderY??p.y)+(p.y-(p.renderY??p.y))*blend;if(Math.hypot(p.x-p.renderX,p.y-p.renderY)>180){p.renderX=p.x;p.renderY=p.y}}const x=mine?g.x:p.renderX,y=mine?g.y:p.renderY;c.save();if(p.hp<=0)c.globalAlpha=.4;const model={...g,hero:{...h,name:p.name,look:p.look,weapon:p.weapon,cosmetic:p.cosmetic},x,y,moving:mine?g.moving:p.moving,invincible:p.inv||0,zaps:0,operatorFire:(p.cooldown||0)>h.shotDelay*.45,shieldCharge:p.shieldCharge,teamColour:mine?'#b7e5b0':'#83cde9'};if(!paintOperator(c,model))fallbackOperator(c,model);roundRect(c,x-26,y+28,52,5,2,'#0b1e2d');roundRect(c,x-26,y+28,52*Math.max(0,p.hp/Math.max(1,p.maxHp)),5,2,mine?'#b7e5b0':'#83cde9');c.font='700 9px system-ui';c.fillStyle='#dbe9e7';c.textAlign='center';c.fillText((mine?'YOU · ':'')+(p.hp>0?p.hp+' HP':'OUT'),x,y+46);c.restore()}};
liveRoster=function(){return live.players.map(p=>{const h={...getBattleHero(p.hero,p.level,equipmentForPeer(p)),look:p.state.look,weapon:p.state.weapon,cosmetic:p.state.cosmetic},me=p.id===live.selfId;return `<article class="live-peer operator-crew-card ${me?'is-you':''}"><button class="crew-portrait" data-operator="${h.id}" data-peer="${p.id}" aria-label="Enlarge and animate ${safeText(p.name)}’s avatar">${petPortrait(h)}<span>INSPECT ↗</span></button><div><small class="crew-role">${p.id===live.hostId?'CREW LEADER':me?'YOUR OPERATOR':'CREWMATE'}</small><b>${safeText(p.name)}${me?' · YOU':''}</b><small>Level ${p.level} · ${p.connected?'Connected':'Reconnecting…'}</small><span class="crew-ready">${live.phase==='quiz'?(p.state.ready?'READY · '+p.state.right+'/10':p.state.progress+'/10 ANSWERED'):h.breed}</span></div><i class="crew-status ${p.connected?'online':''}" aria-label="${p.connected?'Connected':'Reconnecting'}"></i></article>`}).join('')};
function openOperator(id=profile.hero,peerId,forcedCosmetic){const raw=HEROES.find(h=>h.id===id);if(!raw)return;const peer=peerId?(live?.players?.find(p=>p.id===peerId)||live?.units?.[peerId]):null,look=peer?.state?.look||peer?.look||lookFor(id),equipment=peer?equipmentForPeer(peer):equippedItems(),h={...getBattleHero(id,peer?.level||playerLevel(),equipment),look,cosmetic:forcedCosmetic||peer?.state?.cosmetic||peer?.cosmetic};operatorReturn={paused:game?.paused,game,html:modal.open?document.querySelector('#modal-content').innerHTML:null,livePhase:live?.phase};if(game&&!live){game.paused=true;resetControls()}const top=topModal('CHARACTER INSPECTOR').replace('data-action="close"','data-operator-close');openModal(`${top}<div id="operator-spotlight"><div class="operator-stage anim-idle"><div class="operator-stage-grid"></div><div class="operator-halo"></div><div class="operator-showcase">${heroSVG(id,'',look,peer?.state?.weapon||peer?.weapon||profile.weapon,{...equipment,level:peer?.level||playerLevel()},h.cosmetic)}</div><span class="operator-stage-caption">ORIGINAL COMPANION · RANK ${h.rank}</span></div><div class="operator-description"><span class="tag">${forcedCosmetic?'OUTFIT PREVIEW · NO PURCHASE':peer?'LIVE CREW · '+safeText(peer.name):canSelectAvatar(raw)?'UNLOCKED COMPANION':'PREVIEW · UNLOCK AT LEVEL '+raw.level}</span><h2 id="modal-title">${raw.breed}</h2><p>${raw.name} · ${raw.title}</p><div class="operator-metrics"><span><b>${h.hp}</b>BASE LIFE</span><span><b>${h.damage}</b>ATTACK</span><span><b>${h.superDamage}</b>SUPER</span></div><p class="hint">Choose an animation. Your equipped style and gear appear here.</p><div class="operator-actions" role="group" aria-label="Character animation"><button class="secondary" data-operator-animation="idle" aria-pressed="true">Idle</button><button class="secondary" data-operator-animation="walk" aria-pressed="false">Walk</button><button class="secondary" data-operator-animation="attack" aria-pressed="false">Attack</button><button class="secondary" data-operator-animation="celebrate" aria-pressed="false">Celebrate</button></div>${live?.battleStarted?'<p class="hint">The live match continues. Close to return to your crew.</p>':''}<button class="primary" data-operator-close>Back to ${live?'crew':'game'} →</button></div></div>`)}
function closeOperator(){const prior=operatorReturn;operatorReturn=null;closeModal();if(prior?.game===game&&game&&!live){game.paused=!!prior.paused;last=performance.now()}if(prior?.html&&(!live||live.phase===prior.livePhase))openModal(prior.html);else if(live&&!live.battleStarted){live.lastLobby='';drawLiveLobby()}}
previewBreed=function(id){openOperator(id)};
document.addEventListener('click',event=>{const target=event.target.closest('[data-operator],.avatar,[data-operator-close],[data-operator-animation],.rung-art');if(!target)return;if(target.hasAttribute('data-operator-close')){event.preventDefault();event.stopImmediatePropagation();closeOperator();return}if(target.dataset.operatorAnimation){const stage=document.querySelector('.operator-stage');if(stage)stage.className='operator-stage anim-'+target.dataset.operatorAnimation;document.querySelectorAll('[data-operator-animation]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));return}if(target.classList.contains('rung-art')){const row=target.closest('.pet-rung'),id=row?.querySelector('[data-hero]')?.dataset.hero;if(id)openOperator(id);return}event.preventDefault();event.stopImmediatePropagation();openOperator(target.dataset.operator||profile.hero,target.dataset.peer)},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('#operator-spotlight')){event.preventDefault();event.stopImmediatePropagation();closeOperator()}else if((event.key==='Enter'||event.key===' ')&&event.target.closest('.avatar,.rung-art')){event.preventDefault();event.target.click()}},true);
modal.addEventListener('cancel',event=>{if(document.querySelector('#operator-spotlight')){event.preventDefault();closeOperator()}});
document.addEventListener('pointerup',event=>{if(event.target.id!=='arena'||!game||game.alt||game.paused||modal.open)return;const p=canvasGamePoint(event.target,event,game);if(live?.battleStarted){const target=Object.values(live.units).find(u=>Math.hypot(p.x-(u.renderX??u.x),p.y-(u.renderY??u.y)+25)<40);if(target)openOperator(target.hero,target.id)}else if(Math.hypot(p.x-game.x,p.y-game.y+25)<40)openOperator(profile.hero)});
const operatorBar=updateBar;updateBar=function(){operatorBar();const el=document.querySelector('.avatar');if(el){el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','Enlarge and animate your avatar')}};
avatarSprites.clear();initBreedArt();updateBar();
